UPDATE A SET A.HOUSE_NAME = B.HOUSE_NAME, A.HOUSE_ADDR = B.HOUSE_ADDR, A.USE_TEST_DATE = B.USE_TEST_DATE, A.BUILD_COMP = B.BUILD_COMP, A.HOUSE_TYPE = B.HOUSE_TYPE, A.LOT_AREA = B.LOT_AREA, A.DONG_NUM = B.DONG_NUM, A.HOUSE_NUM = B.HOUSE_NUM, A.TOT_GROUND_AREA = B.TOT_GROUND_AREA, A.FLOOR_AREA_RATIO = B.FLOOR_AREA_RATIO, A.BUILD_AREA = B.BUILD_AREA, A.BUILD_LAND_RATIO = B.BUILD_LAND_RATIO, A.BUILD_STRUCTURE = B.BUILD_STRUCTURE, A.WATER_TYPE = B.WATER_TYPE, A.HEAT_TYPE = B.HEAT_TYPE, A.OFFICE_GROUND_AREA = B.OFFICE_GROUND_AREA, A.SILVER_GROUND_AREA = B.SILVER_GROUND_AREA, A.PLAYGROUND_TOT_AREA = B.PLAYGROUND_TOT_AREA, A.RESIDENT_WORKOUT_1 = B.RESIDENT_WORKOUT_1, A.PARK_GROUND_NUM = B.PARK_GROUND_NUM, A.PARK_UNDER_NUM = B.PARK_UNDER_NUM, A.STORAGE_WATER_CAPACITY = B.STORAGE_WATER_CAPACITY, A.ELEVATOR_COMP = B.ELEVATOR_COMP, A.ELEVATOR_NUM = B.ELEVATOR_NUM, A.DV_ROUND = B.DV_ROUND, A.DEFENSIVE_CAPACITY = B.DEFENSIVE_CAPACITY, A.GENERATOR_CAPACITY = B.GENERATOR_CAPACITY, A.REMARKS = B.REMARKS FROM dbo.TRP_HOUSE A JOIN (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.HOUSE_NAME} AS HOUSE_NAME, #{row.HOUSE_ADDR} AS HOUSE_ADDR, #{row.USE_TEST_DATE} AS USE_TEST_DATE, #{row.BUILD_COMP} AS BUILD_COMP, #{row.HOUSE_TYPE} AS HOUSE_TYPE, #{row.LOT_AREA} AS LOT_AREA, #{row.DONG_NUM} AS DONG_NUM, #{row.HOUSE_NUM} AS HOUSE_NUM, #{row.TOT_GROUND_AREA} AS TOT_GROUND_AREA, #{row.FLOOR_AREA_RATIO} AS FLOOR_AREA_RATIO, #{row.BUILD_AREA} AS BUILD_AREA, #{row.BUILD_LAND_RATIO} AS BUILD_LAND_RATIO, #{row.BUILD_STRUCTURE} AS BUILD_STRUCTURE, #{row.WATER_TYPE} AS WATER_TYPE, #{row.HEAT_TYPE} AS HEAT_TYPE, #{row.OFFICE_GROUND_AREA} AS OFFICE_GROUND_AREA, #{row.SILVER_GROUND_AREA} AS SILVER_GROUND_AREA, #{row.PLAYGROUND_TOT_AREA} AS PLAYGROUND_TOT_AREA, #{row.RESIDENT_WORKOUT_1} AS RESIDENT_WORKOUT_1, #{row.PARK_GROUND_NUM} AS PARK_GROUND_NUM, #{row.PARK_UNDER_NUM} AS PARK_UNDER_NUM, #{row.STORAGE_WATER_CAPACITY} AS STORAGE_WATER_CAPACITY, #{row.ELEVATOR_COMP} AS ELEVATOR_COMP, #{row.ELEVATOR_NUM} AS ELEVATOR_NUM, #{row.DV_ROUND} AS DV_ROUND, #{row.DEFENSIVE_CAPACITY} AS DEFENSIVE_CAPACITY, #{row.GENERATOR_CAPACITY} AS GENERATOR_CAPACITY, #{row.REMARKS} AS REMARKS
) B ON A.OFFICE_CODE = B.OFFICE_CODE
